PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>

SELECT $this
WHERE {
    $this nltl:iceLoadCycleCount ?iceCycles ;
          nltl:propellerBladeCount ?bladeCount ;
          nltl:effectiveIceLoadCycleCount ?resultNode .
    ?resultNode qudt:numericValue ?actual .

    BIND ((?iceCycles * ?bladeCount) AS ?expected)
    BIND (
        IF(
            ABS(?expected) < 0.001,
            0.000001,
            0.000001 * ABS(?expected)
        )
        AS ?tolerance
    )
    FILTER (ABS(?actual - ?expected) > ?tolerance)
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX sh: <http://www.w3.org/ns/shacl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:iceLoadCycleCount ?nice ;
          nltl:propellerBladeCount ?blades ;
          nltl:effectiveIceLoadCycleCount ?quantity .
    ?quantity qudt:numericValue ?actual ;
              qudt:unit <http://qudt.org/vocab/unit/UNITLESS> .
    BIND ((?nice * ?blades) AS ?expected)
    FILTER (
        ABS(?actual - ?expected) >
        ((0.000001 * ABS(?expected)) + 0.0000001)
    )
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:propellerType ?type .
    FILTER (?type = "CP" || ?type = "FP")
    FILTER (
        NOT EXISTS {
            $this nltl:hasPropellerBladeLoadCase ?case1 .
            ?case1 nltl:propellerBladeLoadCaseNumber ?number1 .
            FILTER (?number1 = 1)
        }
        ||
        NOT EXISTS {
            $this nltl:hasPropellerBladeLoadCase ?case2 .
            ?case2 nltl:propellerBladeLoadCaseNumber ?number2 .
            FILTER (?number2 = 2)
        }
        ||
        NOT EXISTS {
            $this nltl:hasPropellerBladeLoadCase ?case3 .
            ?case3 nltl:propellerBladeLoadCaseNumber ?number3 .
            FILTER (?number3 = 3)
        }
        ||
        NOT EXISTS {
            $this nltl:hasPropellerBladeLoadCase ?case4 .
            ?case4 nltl:propellerBladeLoadCaseNumber ?number4 .
            FILTER (?number4 = 4)
        }
        ||
        (
            ?type = "FP"
            &&
            EXISTS {
                $this nltl:propellerReversingCapability true
            }
            &&
            NOT EXISTS {
                $this nltl:hasPropellerBladeLoadCase ?case5 .
                ?case5 nltl:propellerBladeLoadCaseNumber ?number5 .
                FILTER (?number5 = 5)
            }
        )
    )
}

