            PREFIX nltl: <https://w3id.org/nltl/vocab#>
            PREFIX qudt: <http://qudt.org/schema/qudt/>
            PREFIX sh: <http://www.w3.org/ns/shacl#>
            PREFIX unit: <http://qudt.org/vocab/unit/>
            PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

            SELECT $this
            WHERE {
                $this nltl:propulsionOutputRestrictionApplies ?restriction ;
                       nltl:maximumContinuousRatingPower ?maximumPower .
                ?maximumPower qudt:numericValue ?maximumValue ;
                              qudt:unit unit:KiloW .
                {
                    $this nltl:propulsionOutputRestrictionApplies ?restriction ; nltl:maximumContinuousRatingPower ?maximumPower .
?maximumPower qudt:numericValue ?maximumValue ; qudt:unit unit:KiloW .
FILTER (?restriction = true)
                    $this nltl:restrictedPropulsionOutput ?comparisonPower .
                    ?comparisonPower qudt:numericValue ?comparisonValue ;
                                     qudt:unit unit:KiloW .
                    FILTER (?maximumValue != ?comparisonValue)
                }
                UNION
                {
                    $this nltl:propulsionOutputRestrictionApplies ?restriction ; nltl:maximumContinuousRatingPower ?maximumPower .
?maximumPower qudt:numericValue ?maximumValue ; qudt:unit unit:KiloW .
FILTER (?restriction = false)
                    $this nltl:propulsionMachineryContinuousOutput ?comparisonPower .
                    ?comparisonPower qudt:numericValue ?comparisonValue ;
                                     qudt:unit unit:KiloW .
                    FILTER (?maximumValue != ?comparisonValue)
                }
            }

            PREFIX nltl: <https://w3id.org/nltl/vocab#>
            PREFIX qudt: <http://qudt.org/schema/qudt/>
            PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

            SELECT $this
            WHERE {
                $this nltl:upperIceWaterlineDisplacement ?duiNode .
                ?duiNode qudt:numericValue ?duiValue .

FILTER NOT EXISTS {
                $this nltl:hasUpperIceWaterlineCase ?case .
                ?case nltl:waterlineCaseDisplacement ?caseDisplacement .
                ?caseDisplacement qudt:numericValue ?caseValue .
                FILTER (?caseValue = ?duiValue)

                FILTER NOT EXISTS {
                    $this nltl:hasUpperIceWaterlineCase ?otherCase .
                    ?otherCase nltl:waterlineCaseDisplacement ?otherDisplacement .
                    ?otherDisplacement qudt:numericValue ?otherValue .
                    FILTER (?otherValue > ?duiValue)
                }

}
            }
